const url = new URL("https://api.airscale.io/v1/find-companies/filter-values");
url.searchParams.set("filter", "industry");
url.searchParams.set("q", "example");

const response = await fetch(url, {
  headers: {
    Authorization: `Bearer ${process.env.AIRSCALE_API_KEY}`
  }
});
const data = await response.json();
console.log(data);

const response = await fetch("https://api.airscale.io/v1/post-likers", {
  method: "POST",
  headers: {
    Authorization: `Bearer ${process.env.AIRSCALE_API_KEY}`,
    "Content-Type": "application/json",
    "Idempotency-Key": process.env.AIRSCALE_PAGE_KEY
  },
  body: JSON.stringify({
  "post_url": "https://example.com/linkedin-post-example",
  "limit": 25
})
});

const data = await response.json();
console.log(data);

const response = await fetch("https://api.airscale.io/v1/post-likers", {
  method: "POST",
  headers: {
    Authorization: `Bearer ${process.env.AIRSCALE_API_KEY}`,
    "Content-Type": "application/json",
    "Idempotency-Key": process.env.AIRSCALE_PAGE_KEY
  },
  body: JSON.stringify({
  "post_url": "https://example.com/linkedin-post-example",
  "limit": 25,
  "cursor": "pje1.synthetic_cursor"
})
});

const data = await response.json();
console.log(data);

import os
import requests

response = requests.post("https://api.airscale.io/v1/post-likers",
  headers={
    "Authorization": f'Bearer {os.environ["AIRSCALE_API_KEY"]}',
    "Content-Type": "application/json",
    "Idempotency-Key": os.environ["AIRSCALE_PAGE_KEY"]
  },
  json={
  "post_url": "https://example.com/linkedin-post-example",
  "limit": 25
}
)
print(response.json())  # Retain any returned retry key before handling errors.
response.raise_for_status()

